"""An offline results view. Missing compiler evidence stays missing, never zero."""
import html,json
from pathlib import Path
LABELS={'teacher':'원형 모델','continuation':'원형 추가 학습','operatorwise':'연산자별 대체','regionwise':'두 구간 대체','single_region':'한 구간 대체','small_student':'소형 학생 모델'}

def render(result,out):
    out=Path(out);out.mkdir(parents=True,exist_ok=True)
    fixture=result.get('scope','').startswith('synthetic') or result['backend']=='cpu-check'
    notice=('합성 RGB 입력으로 실행 경로를 검사한 결과입니다. 자연 이미지 성능이나 외부 컴파일 결과가 아닙니다.' if fixture else '고정된 CIFAR-10 학습 부분집합의 탐색적 비교입니다. 정확도는 CPU 평가, NPU 구간은 컴파일러 관측입니다.')
    rows=[]
    for r in result['records']:
        fp=r['fp32'];q=r.get('tflite_cpu');c=r.get('compiler');t=r.get('training',{})
        rows.append({'seed':r['seed'],'budget':r['budget_steps'],'method':LABELS[r['method']],'parameters':r['parameters'],'updates':t.get('updates',t.get('steps')),'fp32':f"{fp['correct']}/{fp['n']} ({fp['accuracy']*100:.2f}%)",'int8':f"{q['correct']}/{q['n']} ({q['accuracy']*100:.2f}%)" if q else '미실행','cpu_ops':c['host_operator_count'] if c else '미실행','npu_regions':c['npu_partition_count'] if c else '미실행','budget_spent':t.get('budget_spent'),'budget_cap':t.get('budget_cap')})
    data=json.dumps(rows,ensure_ascii=False,allow_nan=False).replace('<','\\u003c')
    agg=result['aggregate'];nseeds=agg['training_replicates'];ntest=agg['unique_test_images'];paired=[]
    for rr in agg['paired_seed_summaries']:
        sd='—' if rr['seed_sd_pp'] is None else f"{rr['seed_sd_pp']:.3f}"
        paired.append(f"<tr><td>{rr['budget_steps']}</td><td>두 구간 − {LABELS[rr['reference']]}</td><td>{rr['mean_delta_pp']:+.3f}%p</td><td>{sd}</td><td>{rr['n_seeds']}</td></tr>")
    paired_html=''.join(paired) or '<tr><td colspan="5">반복 비교가 아직 완성되지 않았습니다. 누락 결과를 0으로 대체하지 않습니다.</td></tr>'
    page='''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NPU Region Repair · 자연 이미지 반복 실험</title><style>*{box-sizing:border-box}body{margin:0;font:15px/1.65 system-ui,sans-serif;color:#172635;background:#f3f6f8}main{max-width:1320px;margin:auto;padding:38px 24px}h1{font-size:32px;line-height:1.3;margin:8px 0}h2{font-size:20px;margin:0 0 12px}.eyebrow{letter-spacing:.1em;font-size:12px;color:#456071}.muted{color:#586875}.banner{background:#fff5de;border-left:4px solid #997024;padding:16px 20px;margin:22px 0}.panel{background:white;border:1px solid #dbe3e9;border-radius:12px;padding:22px;margin:18px 0}.metrics{display:flex;gap:12px;flex-wrap:wrap}.metric{background:white;border:1px solid #dbe3e9;border-radius:10px;padding:14px 22px;flex:1;min-width:180px}.metric strong{font-size:24px;display:block}.scroll{overflow-x:auto;width:100%}table{border-collapse:collapse;width:100%;white-space:nowrap}td,th{text-align:right;border-bottom:1px solid #e2e8ec;padding:11px 13px}th{font-size:12px;background:#f6f8fa}td:first-child,th:first-child{text-align:left}.filters{display:flex;flex-wrap:wrap;gap:14px;align-items:center;margin:16px 0}select{font:inherit;padding:8px;border:1px solid #bdc9d1;border-radius:6px;background:white}label{display:flex;align-items:center;gap:8px}a{color:#235b7d}code{overflow-wrap:anywhere}p{overflow-wrap:anywhere}@media(max-width:480px){main{padding:24px 12px}h1{font-size:26px}.panel{padding:15px}.metric{min-width:120px;padding:12px}}</style></head><body><main><div class="eyebrow">NPU REGION REPAIR / REPEATED-SEED STUDY</div><h1>모델 대체 · 회복 학습 · 경량화</h1><p class="muted">정확도, 학습 예산, 컴파일 결과를 분리해서 비교합니다. NPU 실측 아님.</p>'''
    page+=f'<div class="banner"><strong>{html.escape(notice)}</strong><br>상태: {html.escape(result["status"])}</div>'
    page+=f'<div class="metrics"><div class="metric">학습 시드<strong>{nseeds}개</strong></div><div class="metric">동일 시험 이미지<strong>{ntest:,}장</strong></div><div class="metric">평가 기록<strong>{len(rows)} / {agg["expected_records"]}</strong></div></div>'
    page+='''<section class="panel"><h2>선택된 모델의 최종 평가</h2><div class="filters"><label>학습 시드<select id="seed-filter"><option value="all">전체</option></select></label><label>회복 예산<select id="budget-filter"><option value="all">전체</option></select></label><span id="visible-count" class="muted"></span></div><div class="scroll"><table><thead><tr><th>시드</th><th>예산</th><th>방법</th><th>파라미터</th><th>업데이트</th><th>FP32 CPU</th><th>TFLite CPU</th><th>CPU 잔류 연산</th><th>NPU 실행 구간</th></tr></thead><tbody id="results-body"></tbody></table></div><p class="muted">예산은 원형 모델의 기준 step에 상당하는 Conv/Linear MAC 대리지표입니다. 실제 학습 시간·메모리까지 동일하다는 뜻은 아닙니다.</p></section>'''
    page+='<section class="panel"><h2>사전에 정한 비교: 시드별 대응 차이</h2><div class="scroll"><table><thead><tr><th>예산</th><th>비교 방향</th><th>평균 정확도 차이</th><th>시드 표준편차 (%p)</th><th>시드 수</th></tr></thead><tbody>'+paired_html+'</tbody></table></div><p>같은 시험 이미지를 반복 사용했습니다. 이미지 수를 시드 수만큼 곱하지 않습니다. 양수는 두 구간 대체의 관측 정확도가 더 높다는 뜻일 뿐, 통계적 우위·동등성·신규성을 확정하지 않습니다.</p></section>'
    page+='<section class="panel"><h2>결과를 읽는 범위</h2><p>체크포인트 선택은 검증셋으로만 하고, 모든 시드·예산의 모델을 저장한 뒤 시험셋을 평가합니다. 실패한 시도는 별도로 남으며 성공 경로의 MAC 예산에 섞지 않습니다. 원형 학습 비용도 시드별로 보존합니다.</p><p>Arm Vela의 컴파일 결과는 모빌린트 SDK나 실제 칩의 지연·전력 측정이 아닙니다. 후보 5개는 고정된 비교군이며 임의의 모델을 자동으로 수리하는 도구가 아닙니다.</p><p><a href="summary.json">원시 예측·통계 JSON</a> · <a href="protocol.json">고정 실험 조건</a> · <a href="frozen.json">선택된 가중치 목록</a></p><p class="muted">프로토콜 ID: <code>'+html.escape(result.get('protocol_id',''))+'</code></p></section>'
    page+='<script id="results-data" type="application/json">'+data+'</script>'+'''<script>const rows=JSON.parse(document.getElementById('results-data').textContent);const sf=document.getElementById('seed-filter'),bf=document.getElementById('budget-filter');for(const [el,values] of [[sf,[...new Set(rows.map(x=>x.seed))]],[bf,[...new Set(rows.filter(x=>x.budget!==null).map(x=>x.budget))]]]){for(const v of values){const o=document.createElement('option');o.value=v;o.textContent=v;el.appendChild(o)}}function draw(){const chosen=rows.filter(r=>(sf.value==='all'||String(r.seed)===sf.value)&&(bf.value==='all'||r.budget===null||String(r.budget)===bf.value));const body=document.getElementById('results-body');body.replaceChildren();for(const r of chosen){const tr=document.createElement('tr');for(const v of [r.seed,r.budget??'공통',r.method,r.parameters,r.updates??'—',r.fp32,r.int8,r.cpu_ops,r.npu_regions]){const td=document.createElement('td');td.textContent=v;tr.appendChild(td)}body.appendChild(tr)}document.getElementById('visible-count').textContent=chosen.length+'개 기록';}sf.addEventListener('change',draw);bf.addEventListener('change',draw);draw();</script></main></body></html>'''
    (out/'report.html').write_text(page,encoding='utf-8')
